import { useEffect, useState } from 'react';
import './App.css';
import AdminDashboard from './components/AdminDashboard/AdminDashboard';
import LoginPage from './components/LoginPage';
import RegisterPage from './components/RegisterPage';
import StudentDashboard from './components/StudentDashboard/StudentDashboard';
import api, { getToken, clearToken } from './api';

function App() {
  // 'loading' | 'login' | 'register' | 'student' | 'admin'
  const [currentView, setCurrentView] = useState('loading');
  const [currentUser, setCurrentUser] = useState(null);

  // Auto-fill state for LoginPage after registration
  const [prefilledCredentials, setPrefilledCredentials] = useState({
    email: '',
    password: ''
  });

  // On first load, if a token is already stored (from a previous session),
  // validate it against the backend and restore the session automatically.
  useEffect(() => {
    const token = getToken();
    if (!token) {
      setCurrentView('login');
      return;
    }

    api
      .me()
      .then((user) => {
        setCurrentUser(user);
        setCurrentView(user.role === 'admin' ? 'admin' : 'student');
      })
      .catch(() => {
        clearToken();
        setCurrentView('login');
      });
  }, []);

  // Handle successful registration (account created server-side already;
  // just send them to Login with their email/password pre-filled)
  const handleRegisterSuccess = ({ email, password }) => {
    setPrefilledCredentials({ email, password });
    setCurrentView('login');
  };

  // Handle successful login (token already stored by LoginPage)
  const handleLoginSuccess = (user) => {
    setCurrentUser(user);
    setCurrentView(user.role === 'admin' ? 'admin' : 'student');
  };

  // Handle logout
  const handleLogout = () => {
    clearToken();
    setCurrentUser(null);
    setCurrentView('login');
  };

  if (currentView === 'loading') {
    return <div className="app-container" />;
  }

  return (
    <div className="app-container">
      {currentView === 'login' && (
        <LoginPage
          initialEmail={prefilledCredentials.email}
          initialPassword={prefilledCredentials.password}
          onLoginSuccess={handleLoginSuccess}
          onNavigateToRegister={() => setCurrentView('register')}
        />
      )}

      {currentView === 'register' && (
        <RegisterPage
          onRegisterSuccess={handleRegisterSuccess}
          onNavigateToLogin={() => setCurrentView('login')}
        />
      )}

      {currentView === 'student' && currentUser && (
        <StudentDashboard currentUser={currentUser} onLogout={handleLogout} />
      )}

      {currentView === 'admin' && currentUser && (
        <AdminDashboard currentUser={currentUser} onLogout={handleLogout} />
      )}
    </div>
  );
}

export default App;
